insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0002-0000-4000-8000-000000000023', 'en', null, 'GraphQL & Modern APIs', 'How modern clients ask a server for exactly the data they need. You will move from REST trade-offs to the GraphQL type system, write queries and mutations, wire up resolvers, defeat the N+1 problem with a dataloader, paginate cleanly, handle errors and auth, stream live updates with subscriptions, and finish by designing a small schema of your own. Structure adapted from open web-API curricula on OER Commons (CC BY 4.0); all explanations original.', null, 'career', 35, true, 'technology', '{bbbb0002-0000-4000-8000-000000000019}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-000000000023', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The single biggest difference a client feels when moving from REST to GraphQL is...","options":["GraphQL uses XML instead of JSON","the client asks for exactly the fields it wants from one endpoint","GraphQL cannot send data over HTTP","GraphQL removes the need for a server"],"answer":1,"explanation":"One endpoint, and the client shapes the response -- see ''REST vs GraphQL''."},{"prompt":"In GraphQL, the contract between client and server is defined by...","options":["a folder of URL routes","the database tables directly","a strongly typed schema written in SDL","the HTTP status codes"],"answer":2,"explanation":"The schema (Schema Definition Language) is the typed contract -- see ''The type system and schema''."},{"prompt":"Which operation type is used to change data on the server?","options":["query","mutation","fragment","directive"],"answer":1,"explanation":"Queries read; mutations write -- see ''Mutations''."},{"prompt":"A resolver is best described as...","options":["a caching layer in the browser","a function that returns the value for one field","a database index","a load balancer"],"answer":1,"explanation":"Each field is backed by a resolver function -- see ''Resolvers''."},{"prompt":"Fetching a list of authors and then one query per author for their books is the classic symptom of...","options":["the CORS problem","the N+1 query problem","rate limiting","a memory leak"],"answer":1,"explanation":"1 query for the list plus N for the children -- a dataloader batches them, see ''Nesting and the N+1 problem''."},{"prompt":"To feed a value from the client into a query safely, you use...","options":["string concatenation in the URL","a named variable declared in the operation","a cookie","a global constant"],"answer":1,"explanation":"Variables are declared with a type and passed alongside the query -- see ''Arguments and variables''."},{"prompt":"GraphQL delivers real-time updates over a long-lived connection using...","options":["subscriptions","mutations","enums","scalars"],"answer":0,"explanation":"Subscriptions push new data as events occur -- see ''Subscriptions''."},{"prompt":"When a single field fails but the rest of the response is fine, a well-behaved GraphQL server returns...","options":["HTTP 500 and no data","partial data plus an errors array","an empty body","a redirect"],"answer":1,"explanation":"GraphQL can return partial data with a top-level errors list -- see ''Error handling and auth''."}]}'::jsonb, null, 10),
  (2, 'REST vs GraphQL: when each fits', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain over-fetching and under-fetching, and decide when a REST endpoint or a GraphQL graph is the better tool. Warm-up: from the diagnostic, what is the single biggest change a client feels moving to GraphQL?"},{"heading":"The idea","text":"REST exposes resources at many URLs; you GET /users/1, then GET /users/1/posts, and each route returns a fixed shape. This is simple and caches well over plain HTTP, but two pains show up. Over-fetching: an endpoint hands you 30 fields when your screen needs 3. Under-fetching: one screen needs data from three routes, so the client makes three round trips (the ''waterfall''). GraphQL answers both by exposing a single endpoint and a typed graph: the client sends one query naming exactly the fields it wants, across related types, and gets back a JSON object shaped like the query. The cost is that HTTP caching and simple monitoring get harder, and you must design and maintain a schema."},{"heading":"Worked examples","text":"REST waterfall: GET /authors/7, then GET /authors/7/books, then GET /books/42/reviews -- three requests to render one page. The GraphQL equivalent is one request:\nquery {\n  author(id: 7) {\n    name\n    books {\n      title\n      reviews { rating }\n    }\n  }\n}\nThe response mirrors the query exactly: { \"data\": { \"author\": { \"name\": \"...\", \"books\": [ { \"title\": \"...\", \"reviews\": [ { \"rating\": 5 } ] } ] } } }. Over-fetching example: a REST /products endpoint returns price, description, inventory, supplier, and more for every card in a grid that only shows name and price; a GraphQL query would list just { name price }."},{"heading":"Your turn","text":"1) Name the two data-fetching pains GraphQL is designed to reduce. 2) How many endpoints does a typical GraphQL server expose? 3) Which style makes plain HTTP response caching easier out of the box? 4) A mobile screen needs a user''s name plus the titles of their last 5 orders. Which style avoids a multi-request waterfall? 5) True or false: GraphQL replaces the database. Answers: 1) Over-fetching and under-fetching. 2) One (commonly /graphql). 3) REST, because each URL maps to a cacheable response. 4) GraphQL, in a single query. 5) False -- GraphQL sits in front of data sources; resolvers still read from a database or service."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking GraphQL is a database -- it is a query layer whose resolvers call your real data sources. Mistake: assuming GraphQL is always faster; a careless schema can make more work per request than REST. Exit: (a) What is over-fetching? (b) How many endpoints does GraphQL typically expose? Answers: getting back more fields than the client needs; one."}]}'::jsonb, 'REST models resources as URLs and HTTP verbs; GraphQL models a typed graph queried through one endpoint. Neither is universally ''better'' -- they trade different problems.', 12),
  (3, 'The type system and schema', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read and write a GraphQL schema in SDL: object types, scalars, enums, non-null and list modifiers, and the three special root types. Warm-up: what does the contract between client and server consist of in GraphQL?"},{"heading":"The idea","text":"The schema is a strongly typed description of every type of data and every operation the server offers, written in the Schema Definition Language (SDL). Built-in scalar types are Int, Float, String, Boolean, and ID. You compose object types from fields, each field having its own type. Two modifiers matter: a list is written with square brackets, [Book], and non-null is written with a trailing exclamation mark, String!. An enum restricts a field to a fixed set of values. Three root types are special because they are the entry points: Query (reads), Mutation (writes), and Subscription (live streams). The schema is the single source of truth that both sides validate against."},{"heading":"Worked examples","text":"A small schema:\nenum Role { ADMIN MEMBER GUEST }\n\ntype User {\n  id: ID!\n  name: String!\n  role: Role!\n  books: [Book!]!\n}\n\ntype Book {\n  id: ID!\n  title: String!\n  author: User!\n}\n\ntype Query {\n  user(id: ID!): User\n  books: [Book!]!\n}\nRead the types: User.id is a required ID; User.books is a non-null list whose members are each non-null. Query.user(id: ID!) takes a required ID and returns a User that may be null (for example, not found), while Query.books returns a guaranteed list. Role is an enum, so User.role can only be ADMIN, MEMBER, or GUEST."},{"heading":"Your turn","text":"1) What do the five built-in scalar types include? 2) What does the exclamation mark mean after a type? 3) Write the field ''tags'' as a required list of required strings. 4) Which root type holds operations that read data? 5) Why return User (nullable) rather than User! from a lookup by id? Answers: 1) Int, Float, String, Boolean, ID. 2) Non-null -- the field can never be null. 3) tags: [String!]! 4) Query. 5) A lookup can miss, so null lets the server say ''no such user'' instead of erroring the whole field."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing [Book!]! with [Book]! -- the inner mark constrains the elements, the outer mark constrains the list itself. Mistake: forgetting that Query, Mutation, and Subscription are ordinary object types that happen to be the roots. Exit: (a) What does String! mean? (b) Which root type is used for writes? Answers: a required, never-null string; Mutation."}]}'::jsonb, 'In SDL a trailing exclamation mark means non-null: String! is a required string, and [Book!]! is a non-null list of non-null Books.', 13),
  (4, 'Queries: asking for exactly what you need', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Write query operations with selection sets, aliases, and fragments, and predict the exact shape of the JSON that comes back. Warm-up: how many round trips did the REST waterfall in lesson 2 take, and how many does the GraphQL version take?"},{"heading":"The idea","text":"A query names fields to read; the response is a JSON object whose keys match the fields you selected. The braces after a field form its selection set, and for object-typed fields you must drill down until every leaf is a scalar. An alias renames a field in the response, which lets you ask for the same field twice with different arguments. A fragment is a reusable named block of fields you can spread into multiple selection sets so you do not repeat yourself."},{"heading":"Worked examples","text":"Basic query with a scalar leaf set:\nquery {\n  book(id: \"42\") { title author { name } }\n}\nAliases to fetch two books in one request:\nquery {\n  first: book(id: \"1\") { title }\n  second: book(id: \"2\") { title }\n}\nThe response uses the aliases as keys: { \"data\": { \"first\": { \"title\": \"...\" }, \"second\": { \"title\": \"...\" } } }. A fragment removes repetition:\nfragment BookCard on Book { id title }\n\nquery {\n  featured { ...BookCard }\n  recent { ...BookCard }\n}"},{"heading":"Your turn","text":"1) What is a selection set? 2) Why can you not write ''query { author(id: 1) }'' with no braces after author? 3) What problem does an alias solve? 4) What keyword defines a reusable block of fields? 5) In the aliased example, what are the two top-level keys in data? Answers: 1) The braces listing the fields you want from a type. 2) author returns an object, so you must select its inner fields down to scalars. 3) Asking for the same field more than once (often with different arguments) without a key collision. 4) fragment. 5) first and second."},{"heading":"Common mistakes & exit ticket","text":"Mistake: leaving an object field with no selection set -- the server rejects it. Mistake: expecting the response key to be the field name when you used an alias; the alias wins. Exit: (a) What shapes the JSON response? (b) What does a fragment let you avoid? Answers: the selection set of the query; repeating the same field list across queries."}]}'::jsonb, 'A selection set is the block in braces listing the fields you want. For any object type you must select down to scalar fields -- you cannot ''select an object'' without naming its inner fields.', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Getting back 30 fields when your screen needs 3 is called...","options":["under-fetching","over-fetching","batching","caching"],"answer":1,"explanation":"Over-fetching is receiving more than you asked to display -- see ''REST vs GraphQL''."},{"prompt":"In SDL, the type [String!]! describes...","options":["a nullable list of nullable strings","a non-null list of non-null strings","a single required string","an enum of strings"],"answer":1,"explanation":"Inner mark = elements non-null, outer mark = list non-null -- see ''The type system and schema''."},{"prompt":"Which root type is the entry point for reads?","options":["Mutation","Subscription","Query","Scalar"],"answer":2,"explanation":"Query holds read operations -- see ''The type system and schema''."},{"prompt":"An alias in a query is used to...","options":["encrypt a field","rename a field in the response so you can request it twice","delete a field","cache a field"],"answer":1,"explanation":"Aliases give each copy of a field a distinct response key -- see ''Queries''."},{"prompt":"For an object-typed field, you must...","options":["leave it empty","provide a selection set down to scalar leaves","wrap it in quotes","give it an HTTP verb"],"answer":1,"explanation":"You select inner fields until every leaf is a scalar -- see ''Queries''."},{"prompt":"GraphQL typically exposes how many HTTP endpoints?","options":["one per resource","one total","two","one per field"],"answer":1,"explanation":"A single endpoint, commonly /graphql -- see ''REST vs GraphQL''."}]}'::jsonb, null, 8),
  (6, 'Mutations: changing data', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Write mutation operations to create, update, and delete data, use input types for arguments, and read back a useful result in the same request. Warm-up: which operation type changes data, and how does it differ from a query in structure?"},{"heading":"The idea","text":"Mutations are the writes: create, update, delete. Structurally a mutation looks like a query but lives under the Mutation root, and by convention the server runs top-level mutation fields in series (one after another) rather than in parallel, so ordered writes are predictable. Because a mutation returns a type, you select fields from the result to get the new state back without a second round trip. When a write takes many fields, group them into an input type (declared with the ''input'' keyword) so the mutation signature stays readable."},{"heading":"Worked examples","text":"Schema side:\ninput CreateBookInput {\n  title: String!\n  authorId: ID!\n}\n\ntype Mutation {\n  createBook(input: CreateBookInput!): Book!\n  deleteBook(id: ID!): Boolean!\n}\nClient side, creating and reading the result back:\nmutation {\n  createBook(input: { title: \"Graphs\", authorId: \"7\" }) {\n    id\n    title\n    author { name }\n  }\n}\nThe response returns the fields you selected on the new Book, so the client can update its cache immediately. A delete:\nmutation {\n  deleteBook(id: \"42\")\n}\nreturns a Boolean telling you whether the row was removed."},{"heading":"Your turn","text":"1) Which root type holds writes? 2) Why does a mutation have a selection set at all? 3) What keyword declares a group of arguments as one object? 4) In what order do top-level mutation fields run by convention? 5) Rewrite deleteBook so it returns the deleted Book instead of a Boolean. Answers: 1) Mutation. 2) To read fields off the result of the write in the same request. 3) input. 4) In series, one after another. 5) deleteBook(id: ID!): Book -- return the removed record (nullable if it might not exist)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: expecting top-level mutation fields to run in parallel; the spec runs them serially so ordering is safe. Mistake: forgetting to select a return field, then wondering why you got nothing useful back. Exit: (a) What is an input type for? (b) Why select fields on a mutation result? Answers: bundling many write arguments into one named object; to read the new state back in the same request."}]}'::jsonb, 'A mutation still has a selection set: after the write, you choose which fields of the result to read back. Group many write arguments into an input type to keep signatures clean.', 12),
  (7, 'Resolvers: how fields get their values', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what a resolver is, read the four resolver arguments, and trace how a nested query resolves field by field. Warm-up: in one sentence, what backs each field in a GraphQL response?"},{"heading":"The idea","text":"Every field is backed by a resolver: a function that returns that field''s value. A resolver receives four arguments in order: parent (the object resolved one level up, sometimes called root or source), args (the field''s arguments), context (per-request shared state such as the current user, database handles, and loaders), and info (details about the query itself). When a field is a scalar and the parent object already has it, the default resolver simply reads parent.fieldName, so you only write resolvers where real work happens. GraphQL resolves a query top-down: it resolves Query.author, then passes that author as parent into the resolver for author.books, and so on down the tree."},{"heading":"Worked examples","text":"A resolver map (JavaScript-style pseudocode):\nconst resolvers = {\n  Query: {\n    author: (parent, args, context) => context.db.findAuthor(args.id)\n  },\n  Author: {\n    books: (author, args, context) => context.db.booksByAuthor(author.id)\n  }\n};\nHere Query.author reads args.id and returns an author object. Then for author.books, the just-resolved author arrives as the first argument, and its id drives the lookup. Author.name needs no resolver because the author object already carries name, so the default resolver returns author.name. context.db is shared per request, set up once when the request starts."},{"heading":"Your turn","text":"1) In order, what are the four resolver arguments? 2) Which argument carries the current user? 3) Where does a field''s arguments show up in the resolver? 4) When can you rely on the default resolver? 5) In resolving author.books, what is the value of the first argument? Answers: 1) parent, args, context, info. 2) context. 3) args. 4) When the parent object already has a property with that field''s name. 5) The author object resolved by Query.author."},{"heading":"Common mistakes & exit ticket","text":"Mistake: putting per-request state (like the logged-in user) in a module global instead of context, which leaks data across requests. Mistake: writing a resolver for every scalar when the default already reads it off the parent. Exit: (a) What does the parent argument hold? (b) What belongs in context? Answers: the value resolved one level up; per-request shared state such as the current user and data loaders."}]}'::jsonb, 'A resolver signature is (parent, args, context, info). The ''parent'' is the value resolved one level up; ''context'' carries per-request state like the current user and shared loaders.', 13),
  (8, 'Arguments and variables', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Pass arguments to fields, parameterize operations with typed variables, and set default values, keeping user input out of the query text. Warm-up: how does GraphQL let you reuse one query with different inputs?"},{"heading":"The idea","text":"Fields can take arguments, declared in the schema with a type: user(id: ID!). To make a query reusable and safe, you declare variables in the operation signature and reference them by their $name. The client then sends a separate JSON object of variable values alongside the query. This keeps the query text constant (good for caching and for avoiding injection through string building) while the inputs change per call. Variables can also carry a default value, used when the client omits them."},{"heading":"Worked examples","text":"A parameterized query:\nquery GetUser($id: ID!) {\n  user(id: $id) { name role }\n}\nsent with variables:\n{ \"id\": \"7\" }\nA variable with a default and a filter argument:\nquery Books($limit: Int = 10, $role: Role) {\n  books(first: $limit) { title }\n  users(role: $role) { name }\n}\nIf the client sends no limit, first defaults to 10. Because the query string never changes, the server can parse and cache the operation once and just swap the variable values on each call."},{"heading":"Your turn","text":"1) How do you declare a required ID variable in an operation? 2) Where do the actual variable values travel? 3) Why is building the query by pasting user input into the string a bad idea? 4) How do you give a variable a default of 10? 5) In GetUser, what is the type of $id? Answers: 1) query Name($id: ID!) { ... }. 2) In a separate JSON variables object sent with the request. 3) It defeats caching and opens the door to injection; typed variables are validated instead. 4) $limit: Int = 10. 5) ID! (a required ID)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: interpolating client values directly into the query string instead of using variables. Mistake: declaring a variable but forgetting to reference it in a field, which is an error. Exit: (a) Where do variable values go? (b) How do you mark a variable required? Answers: in a separate variables JSON object; give its type a trailing exclamation mark, like ID!."}]}'::jsonb, 'Declare a variable in the operation signature with a type ($id: ID!), then reference it in the field. Send the values in a separate JSON ''variables'' object -- never by pasting them into the query string.', 12),
  (9, 'Nesting and the N+1 problem', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Recognize the N+1 query problem that nesting creates, and fix it with a batching, per-request dataloader. Warm-up: fetching 50 authors and then each author''s books separately makes how many database calls?"},{"heading":"The idea","text":"Nesting is GraphQL''s superpower, but a naive resolver tree can hammer your database. Suppose you resolve a list of N authors, and for each one the books resolver runs its own query. That is 1 query for the authors plus N queries for their books: the N+1 problem. The fix is a dataloader. Instead of each resolver querying immediately, it hands its key (say an author id) to a loader. The loader waits until the current tick has collected all the keys, then fires one batched query (WHERE author_id IN (...)), and returns each resolver its matching rows. It also caches by key within the request, so asking for the same id twice hits the database once. Create a fresh loader per request and put it on context."},{"heading":"Worked examples","text":"The query that triggers it:\nquery {\n  authors { name books { title } }\n}\nWithout batching: 1 query for authors, then one books query per author -> 1 + N. With a loader on context:\nconst resolvers = {\n  Author: {\n    books: (author, args, context) => context.loaders.booksByAuthor.load(author.id)\n  }\n};\nEach call to load(author.id) just enqueues the id; the loader''s batch function runs once with all ids and issues a single SELECT ... WHERE author_id IN (id1, id2, ...). Fifty authors now cost 2 queries instead of 51. Because loaders are per request, one user''s cache never bleeds into another''s."},{"heading":"Your turn","text":"1) For a list of 50 authors resolved naively, how many queries does the books field cause in total? 2) What does a dataloader do with the keys it collects during a tick? 3) Why must a loader be created per request rather than once at startup? 4) What SQL pattern does the batch function typically use? 5) If the same author id is requested twice in one query, how many database hits with a loader? Answers: 1) 1 + 50 = 51. 2) Batches them into a single lookup and returns each resolver its slice. 3) So its cache does not leak data across users and stays consistent for that request. 4) WHERE ... IN (list of ids). 5) One, thanks to per-request caching."},{"heading":"Common mistakes & exit ticket","text":"Mistake: sharing one loader across all requests, which leaks cached data between users. Mistake: ''fixing'' N+1 by removing nesting from the schema instead of batching the resolver. Exit: (a) What is the N+1 problem? (b) What two things does a dataloader do? Answers: 1 query for a list plus N for its children; it batches keys into one query and caches by key within the request."}]}'::jsonb, 'A dataloader collects all the ids requested during one tick, fires a single batched lookup, and hands each resolver its slice -- turning N calls into 1. It also caches within the request so a repeated id is fetched once.', 14),
  (10, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"The four resolver arguments, in order, are...","options":["args, parent, info, context","parent, args, context, info","context, args, parent, info","parent, context, args, info"],"answer":1,"explanation":"parent, args, context, info -- see ''Resolvers''."},{"prompt":"Per-request state like the current user belongs in...","options":["a module global","the args argument","the context argument","the info argument"],"answer":2,"explanation":"context carries per-request shared state -- see ''Resolvers''."},{"prompt":"Client values should reach a query through...","options":["string concatenation","typed variables sent in a separate JSON object","HTTP headers only","the URL path"],"answer":1,"explanation":"Typed variables keep the query constant and safe -- see ''Arguments and variables''."},{"prompt":"Resolving 50 authors and then each author''s books one query at a time costs how many queries?","options":["1","50","51","100"],"answer":2,"explanation":"1 for the authors plus 50 for the books = 51 -- the N+1 problem, see ''Nesting and the N+1 problem''."},{"prompt":"A dataloader defeats N+1 primarily by...","options":["deleting nested fields","batching many keys into a single query","adding more endpoints","disabling caching"],"answer":1,"explanation":"It collects keys for a tick and fires one batched lookup -- see ''Nesting and the N+1 problem''."},{"prompt":"Top-level mutation fields run...","options":["in parallel","in random order","in series, one after another","never"],"answer":2,"explanation":"The spec runs them serially so ordering is predictable -- see ''Mutations''."}]}'::jsonb, null, 8),
  (11, 'Pagination: slicing large lists', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compare offset and cursor pagination, read a Relay-style connection, and page through results with first/after. Warm-up: if you page by ''skip 20, take 10'' and someone inserts a row at the top, what goes wrong?"},{"heading":"The idea","text":"You cannot return ten thousand rows in one field, so you page. Offset pagination uses arguments like offset (or skip) and limit: page 3 is skip 20, take 10. It is easy but fragile -- inserting or deleting rows shifts every offset, so items get repeated or missed. Cursor pagination instead returns an opaque cursor marking each item''s position; the next page says ''give me the first N after this cursor'', which stays stable under inserts. The widely used Relay connection standard formalizes this: a connection field returns edges (each an object with a node and a cursor) plus a pageInfo object carrying hasNextPage and endCursor."},{"heading":"Worked examples","text":"A connection-style schema:\ntype BookConnection {\n  edges: [BookEdge!]!\n  pageInfo: PageInfo!\n}\ntype BookEdge { node: Book! cursor: String! }\ntype PageInfo { hasNextPage: Boolean! endCursor: String }\n\ntype Query {\n  books(first: Int!, after: String): BookConnection!\n}\nFirst page:\nquery {\n  books(first: 10) {\n    edges { cursor node { title } }\n    pageInfo { hasNextPage endCursor }\n  }\n}\nTo get the next page, resend with after set to the endCursor you just received: books(first: 10, after: \"opaque-cursor\"). When pageInfo.hasNextPage is false, you have reached the end."},{"heading":"Your turn","text":"1) Why can offset pagination repeat or skip items? 2) What two things does a Relay edge contain? 3) Which pageInfo field tells you whether to keep going? 4) How do you request the page after the one you just got? 5) Which pagination style is stable when rows are inserted at the top? Answers: 1) Inserts or deletes shift every offset, so the window slides. 2) A node (the item) and a cursor (its position). 3) hasNextPage. 4) Pass after: <the previous endCursor>. 5) Cursor pagination."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating a cursor as a row number to do math on -- it is an opaque token you pass back unchanged. Mistake: paging with offsets over data that changes often, causing duplicates. Exit: (a) What does an edge hold? (b) What does hasNextPage tell you? Answers: a node and its cursor; whether another page exists after the current one."}]}'::jsonb, 'Offset pagination (skip/limit) is simple but drifts when rows are inserted. Cursor pagination points at a stable position, which is why the Relay connection pattern (edges, node, cursor, pageInfo) is the common standard.', 13),
  (12, 'Error handling and auth', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Interpret the data-plus-errors response shape, place authentication and authorization correctly, and return safe error messages. Warm-up: if one field of a big query fails, should the whole response fail?"},{"heading":"The idea","text":"GraphQL usually returns HTTP 200 even for logical errors; the body itself reports problems. A response can contain a top-level data object and a top-level errors array at the same time, so a single failing field can be null while the rest of the data comes through -- partial success. Authentication (who are you) is typically handled once per request, before resolvers run, by reading a token and putting the resulting user on context. Authorization (what may you do) lives inside resolvers, which check context.user before returning sensitive fields. Keep error messages typed and generic for clients (an error code, not a raw stack trace), and log the full detail server-side."},{"heading":"Worked examples","text":"A partial response:\n{\n  \"data\": { \"me\": { \"name\": \"Noelia\" }, \"secret\": null },\n  \"errors\": [ { \"message\": \"Not authorized\", \"path\": [\"secret\"], \"extensions\": { \"code\": \"FORBIDDEN\" } } ]\n}\nHere ''me'' resolved fine while ''secret'' failed and became null, with a matching entry in errors that names the path and a machine-readable code. Authorization inside a resolver:\nconst resolvers = {\n  Query: {\n    secret: (parent, args, context) => {\n      if (!context.user) throw new Error(\"Not authorized\");\n      return context.db.getSecret();\n    }\n  }\n};\nThe token was verified earlier when context was built, so the resolver only checks the result."},{"heading":"Your turn","text":"1) Can a single response contain both data and errors? 2) What is the difference between authentication and authorization? 3) Where is the current user usually placed for resolvers to read? 4) Why send a generic message and code instead of a raw stack trace? 5) What does the ''path'' field in an error tell you? Answers: 1) Yes -- partial data with a matching errors entry. 2) Authentication is who you are; authorization is what you are allowed to do. 3) On context. 4) To avoid leaking internal detail; keep full detail in server logs. 5) Which field in the query produced the error."},{"heading":"Common mistakes & exit ticket","text":"Mistake: failing the entire response for one unauthorized field instead of nulling that field and adding an error. Mistake: returning raw exception text to clients, leaking internals. Exit: (a) What two top-level keys can a response carry together? (b) Where does authorization logic live? Answers: data and errors; inside resolvers, checking context.user."}]}'::jsonb, 'A GraphQL response can carry both data and errors at once. Do most authorization inside resolvers using context.user, and expose typed, non-leaky messages to clients.', 13),
  (13, 'Subscriptions: real-time updates', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how subscriptions differ from queries, write a subscription operation, and describe the publish/subscribe flow behind it. Warm-up: which operation type would you use to power a live chat feed?"},{"heading":"The idea","text":"Queries and mutations are request-response: one message out, one message back. Subscriptions are different -- the client opens a persistent connection (commonly a WebSocket) and the server pushes a fresh payload each time a named event occurs. On the server, a mutation that changes state publishes an event to a topic; every client subscribed to that topic receives the new data. This is how live dashboards, chat, and notification badges stay current without polling. A subscription operation has the same selection-set shape as a query, so the client still chooses exactly which fields of the pushed object it wants."},{"heading":"Worked examples","text":"Schema:\ntype Subscription {\n  bookAdded: Book!\n}\nClient operation:\nsubscription {\n  bookAdded { id title author { name } }\n}\nServer side, the createBook mutation publishes after it writes:\ncreateBook: async (parent, args, context) => {\n  const book = await context.db.insertBook(args.input);\n  context.pubsub.publish(\"BOOK_ADDED\", { bookAdded: book });\n  return book;\n}\nEvery client holding the bookAdded subscription immediately receives { \"data\": { \"bookAdded\": { \"id\": \"...\", \"title\": \"...\" } } } over its open connection, shaped by its own selection set."},{"heading":"Your turn","text":"1) How does a subscription differ from a query in the number of responses? 2) What transport commonly carries subscriptions? 3) What does a mutation do so subscribers get notified? 4) Do subscriptions still use selection sets? 5) Name one feature that subscriptions are well suited to build. Answers: 1) A query returns once; a subscription streams many payloads over time. 2) A WebSocket. 3) It publishes an event to a topic that subscribers listen on. 4) Yes -- the client still picks the fields it wants. 5) Live chat, notifications, or a real-time dashboard (any of these)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reaching for subscriptions when simple polling would do -- they add a stateful connection to operate. Mistake: forgetting to publish from the mutation, so subscribers never hear about the change. Exit: (a) What is the third root type? (b) What must a mutation call so subscribers receive an update? Answers: Subscription; publish (to the topic the subscription listens on)."}]}'::jsonb, 'A subscription is the third root type. Unlike a query (one response) it opens a long-lived stream (commonly over WebSocket) that pushes a new payload every time its event fires.', 12),
  (14, 'Schema design best practices', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Apply core schema design habits: client-driven naming, sensible nullability, mutation payload types, and additive versioning. Warm-up: should your GraphQL types mirror your database tables one-for-one?"},{"heading":"The idea","text":"A good schema is designed for the clients that consume it, not copied from your storage layer. Name types and fields in the domain''s language (User, Order, publishedAt), not in table-and-column shorthand. Choose nullability deliberately: mark a field non-null only when the server can always supply it, and leave it nullable when null carries meaning (not found, not permitted). Prefer a mutation that returns a payload type wrapping the affected object plus any user-facing errors, rather than a bare Boolean, so clients can react precisely. GraphQL avoids URL-style versioning: you evolve by adding new fields and types, and by marking old ones with the @deprecated directive instead of removing them, so existing clients keep working. Keep resolvers thin and push real logic into a service layer."},{"heading":"Worked examples","text":"A payload-returning mutation with deprecation:\ntype CreateBookPayload {\n  book: Book\n  userErrors: [UserError!]!\n}\ntype UserError { field: String message: String! }\n\ntype Mutation {\n  createBook(input: CreateBookInput!): CreateBookPayload!\n}\n\ntype Book {\n  id: ID!\n  title: String!\n  subtitle: String @deprecated(reason: \"Use title\")\n}\nThe payload lets a client read back the new book and any validation problems in one shot. The @deprecated field still resolves for old clients while tooling steers new clients to title. Nullability at work: Query.book(id: ID!): Book is nullable because a lookup can miss, while Book.title is String! because a stored book always has one."},{"heading":"Your turn","text":"1) Should schema types mirror database tables? 2) When should a field be non-null? 3) Why return a payload type from a mutation instead of a Boolean? 4) How does GraphQL usually handle versioning? 5) What directive marks a field as outdated without removing it? Answers: 1) No -- design for client needs and domain language. 2) Only when the server can always provide a value. 3) So the client gets the affected object plus structured errors in one response. 4) Additively -- add new fields and deprecate old ones rather than cutting URL versions. 5) @deprecated."},{"heading":"Common mistakes & exit ticket","text":"Mistake: marking everything non-null, so one missing value errors a whole branch. Mistake: deleting or renaming a field in place, breaking existing clients instead of deprecating it. Exit: (a) What should drive schema shape? (b) How do you retire a field safely? Answers: the needs of the clients (the domain), not the database tables; deprecate it with @deprecated and add its replacement."}]}'::jsonb, 'Design the schema around what clients need, not around your database tables. Favor non-null where a value is guaranteed, nullable where failure or absence is meaningful, and evolve by adding fields rather than breaking old ones.', 13),
  (15, 'Checkpoint 3', 'quiz', '{"questions":[{"prompt":"Cursor pagination is preferred over offset pagination because it...","options":["returns more rows","stays stable when rows are inserted or deleted","needs no arguments","is required by HTTP"],"answer":1,"explanation":"A cursor marks a stable position; offsets drift on inserts -- see ''Pagination''."},{"prompt":"A GraphQL response that returns some data and one error entry represents...","options":["a fatal crash","partial success with a failed field","a cache miss","a redirect"],"answer":1,"explanation":"data and errors can coexist; the failed field is null -- see ''Error handling and auth''."},{"prompt":"Authorization checks are best placed...","options":["in the URL","inside resolvers using context.user","in the client only","in the schema comments"],"answer":1,"explanation":"Resolvers check context.user before returning sensitive fields -- see ''Error handling and auth''."},{"prompt":"For a live chat feed, the right operation type is...","options":["query","mutation","subscription","fragment"],"answer":2,"explanation":"Subscriptions push updates over a persistent connection -- see ''Subscriptions''."},{"prompt":"GraphQL typically handles versioning by...","options":["adding /v2 to the URL","adding fields and deprecating old ones","removing old fields immediately","returning XML"],"answer":1,"explanation":"Evolve additively with @deprecated -- see ''Schema design best practices''."},{"prompt":"The Relay connection pattern exposes a page''s items through...","options":["a flat array only","edges with node and cursor, plus pageInfo","HTTP headers","a single scalar"],"answer":1,"explanation":"edges (node + cursor) and pageInfo carry the page -- see ''Pagination''."}]}'::jsonb, null, 8),
  (16, 'Capstone: design a small GraphQL API', 'reading', '{"sections":[{"heading":"The task","text":"Design the full schema for a small book-review service and sketch its resolvers. Users write reviews on books; an author has many books; a book has many reviews. Produce complete SDL plus a short plan for resolvers, pagination, the N+1 fix, auth, and one real-time feature. Treat this as something you would hand a teammate to implement."},{"heading":"The structure to follow","text":"1) Object types: define User, Author, Book, and Review with deliberate nullability. 2) Query root: at least a paginated books(first, after) connection and a single book(id) lookup. 3) Mutation root: createReview returning a payload type with the review and userErrors. 4) Subscription root: reviewAdded(bookId) so a book page updates live. 5) Resolvers and loaders: name which fields need custom resolvers and where a dataloader batches (Book.reviews, Author.books). 6) Cross-cutting: say where auth is checked and how errors surface."},{"heading":"A fully worked model (of a different domain)","text":"For a task tracker, a complete slice looks like:\ntype Project { id: ID! name: String! tasks(first: Int!, after: String): TaskConnection! }\ntype Task { id: ID! title: String! done: Boolean! project: Project! }\ntype TaskConnection { edges: [TaskEdge!]! pageInfo: PageInfo! }\ntype TaskEdge { node: Task! cursor: String! }\ntype PageInfo { hasNextPage: Boolean! endCursor: String }\n\ninput AddTaskInput { projectId: ID! title: String! }\ntype AddTaskPayload { task: Task userErrors: [UserError!]! }\ntype UserError { field: String message: String! }\n\ntype Query { project(id: ID!): Project }\ntype Mutation { addTask(input: AddTaskInput!): AddTaskPayload! }\ntype Subscription { taskAdded(projectId: ID!): Task! }\nResolver plan: Project.tasks uses cursor pagination; Task.project is batched with a loader keyed by projectId to avoid N+1; addTask verifies context.user, inserts, then pubsub.publish(''TASK_ADDED'', ...) so taskAdded subscribers update. Use this only as a template of shape and rigor -- do not copy it; your deliverable is the book-review service above."},{"heading":"Self-check rubric","text":"Check yes to each: every object type sets non-null only where a value is guaranteed and leaves lookups nullable; the books field returns a connection with edges, node, cursor, and pageInfo; createReview returns a payload type carrying the review and a userErrors list rather than a bare Boolean; you named at least one place a dataloader batches (Book.reviews or Author.books) to kill N+1; you stated where auth is checked (in the resolver via context.user); the reviewAdded subscription is published from the createReview mutation. If all six are true, you have designed a coherent, production-shaped GraphQL API."}]}'::jsonb, 'Work top-down: types first, then Query, then Mutation, then Subscription, then the resolvers and loaders that back them. Justify each nullability and each pagination choice out loud.', 16),
  (17, 'Final quiz', 'quiz', '{"questions":[{"prompt":"The core promise of a GraphQL query is that...","options":["it always returns every field","the client gets back exactly the fields it selected","it only works over WebSocket","it bypasses resolvers"],"answer":1,"explanation":"The response mirrors the selection set -- see ''Queries''."},{"prompt":"In SDL, Query.user(id: ID!): User (nullable return) is a good choice because...","options":["users never exist","a lookup by id can miss, so null means not found","IDs are optional","nullability is illegal on roots"],"answer":1,"explanation":"Nullable returns let a miss say ''not found'' instead of erroring -- see ''The type system and schema'' and ''Schema design''."},{"prompt":"The right way to send a user-provided id into a query is...","options":["paste it into the query string","declare a typed variable and send it in the variables object","put it in a cookie","hard-code it"],"answer":1,"explanation":"Typed variables keep the query constant and safe -- see ''Arguments and variables''."},{"prompt":"A dataloader turns the N+1 pattern into...","options":["N+1 still","2 queries via batching","zero queries","N squared queries"],"answer":1,"explanation":"One list query plus one batched child query -- see ''Nesting and the N+1 problem''."},{"prompt":"To page stably through a large, frequently changing list, use...","options":["offset and limit","cursor-based connections","no pagination","random sampling"],"answer":1,"explanation":"Cursors stay stable under inserts; offsets drift -- see ''Pagination''."},{"prompt":"A response with data.me populated and data.secret null plus an errors entry is...","options":["a total failure","partial success","impossible in GraphQL","a cache artifact"],"answer":1,"explanation":"data and errors coexist; the failed field is null -- see ''Error handling and auth''."},{"prompt":"To push new data to clients as events happen, you use...","options":["a query","a mutation","a subscription","a fragment"],"answer":2,"explanation":"Subscriptions stream over a persistent connection -- see ''Subscriptions''."},{"prompt":"The recommended way to evolve a GraphQL schema without breaking clients is to...","options":["version the URL as /v2","add fields and mark old ones @deprecated","delete old fields immediately","switch to REST"],"answer":1,"explanation":"Evolve additively and deprecate -- see ''Schema design best practices''."},{"prompt":"Per-request state such as the current user should be carried in the resolver''s...","options":["parent","args","context","info"],"answer":2,"explanation":"context holds per-request shared state -- see ''Resolvers''."},{"prompt":"A mutation that returns a payload type (object + userErrors) is preferred over a bare Boolean because...","options":["Booleans are deprecated","the client can read the affected object and structured errors in one response","it is required by HTTP","it removes the need for resolvers"],"answer":1,"explanation":"Payload types give the client the new state plus precise errors -- see ''Schema design best practices''."}]}'::jsonb, null, 10)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000023' and l.position = v.pos
);
